sys_hub_input_scripts.script:
{"short_description":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
return fd_data._2__get_catalog_variables.customer.name.toString() + " Repair Request for Device - " + fd_data._2__get_catalog_variables.device_reference.serial_number.toString();","savedValue":""}}

{"ah_short_description":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
return "Repair Device - " + fd_data._2__get_catalog_variables.device_reference.serial_number.toString();"}}

{"ah_short_description":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
return "Ship Device - " + fd_data._2__get_catalog_variables.device_reference.serial_number.toString();"}}

